import type * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

/**
 * Brand logo from the identity assets: content.mark is the assets.mark glyph
 * (the Studio mark), content.lockup is that mark beside the live-text wordmark
 * laid out as assets.lockup (rule identity-lockup@1). Pass `mark` to swap in a
 * consumer's own glyph; ground.inverse is for dark or brand-colored grounds.
 */
const logoVariants = cva("inline-flex shrink-0 items-center font-heading font-semibold tracking-tight", {
  variants: {
    size: {
      sm: "h-5 gap-1.5 text-sm [&_[data-slot=logo-mark]]:size-5",
      md: "h-7 gap-2 text-lg [&_[data-slot=logo-mark]]:size-7",
      lg: "h-12 gap-3 text-3xl [&_[data-slot=logo-mark]]:size-12",
    },
    ground: {
      base: "text-foreground [--logo-knockout:var(--background)]",
      inverse: "text-background [--logo-knockout:var(--foreground)]",
    },
  },
  defaultVariants: { size: "md", ground: "base" },
})

function StudioMark(props: React.ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 32 32" aria-hidden="true" {...props}>
      <rect width="32" height="32" rx="8" fill="currentColor" />
      <path d="M23 10H13a6 6 0 0 0 0 12h10M23 16H13" stroke="var(--logo-knockout)" strokeWidth="2" fill="none" />
    </svg>
  )
}

function Logo({
  content = "mark",
  name = "Clossys",
  mark,
  size,
  ground,
  className,
  ...props
}: React.ComponentProps<"span"> &
  VariantProps<typeof logoVariants> & {
    content?: "mark" | "lockup"
    name?: string
    mark?: React.ReactNode
  }) {
  return (
    <span
      data-slot="logo"
      data-content={content}
      role="img"
      aria-label={name}
      className={cn(logoVariants({ size, ground }), className)}
      {...props}
    >
      <span data-slot="logo-mark" className="flex shrink-0 [&>svg]:size-full">
        {mark ?? <StudioMark />}
      </span>
      {content === "lockup" && (
        <span aria-hidden="true" className="leading-none">
          {name}
        </span>
      )}
    </span>
  )
}

export { Logo, logoVariants }
